public extension PhosphorIcon {
    /// Draws the glyph at `size` px (the React `size` prop) centered in `rect`.
    func draw(_ c: CanvasContext, in rect: CanvasRect, color: CanvasColor) {
        c.fillSVG(paths, viewBox: 256, in: rect, color)
    }
    /// Draws the glyph `size`×`size` centered on `center`.
    func draw(_ c: CanvasContext, center: CanvasPoint, size: Double, color: CanvasColor) {
        draw(c, in: CanvasRect(x: center.x - size / 2, y: center.y - size / 2, width: size, height: size), color: color)
    }
}
